\[ M[i][j] = \max \begin{cases} M[i-1][j-1] + score(SEQA[i-1], SEQB[j-1]) \\ M[i-1][j] + GAP_SCORE \\ M[i][j-1] + GAP_SCORE \end{cases} \]
